input.command:
(npm start >$TMPDIR/srv.log 2>&1 &) ; sleep 1.5; cat > $TMPDIR/shot.mjs <<'EOF'
import { chromium } from '@playwright/test';
const b = await chromium.launch();
for (const w of [1280, 900, 375]) {
  const p = await b.newPage({ viewport: { width: w, height: 900 } });
  await p.goto(`http://127.0.0.1:${process.env.PORT}/contact.html`);
  await p.screenshot({ path: `${process.env.TMPDIR}/contact-${w}.png`, fullPage: true });
  const o = await p.evaluate(() => [...document.querySelectorAll('body *')].filter(e => e.scrollWidth > e.clientWidth + 1 && getComputedStyle(e).overflow==='visible').map(e => e.tagName+'.'+e.className+' '+e.scrollWidth+'>'+e.clientWidth).slice(0,10).concat(['doc '+document.documentElement.scrollWidth]));
  console.log(w, o);
}
await b.close();
EOF
cp $TMPDIR/shot.mjs ./.shot.mjs && node .shot.mjs; rm .shot.mjs

